public static METExciseInformationTableUpdateController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METExciseInformationTableUpdateController controller = new METExciseInformationTableUpdateController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// New method to create instance of class
/// </summary>
protected void new()
{
    super(classStr(METExciseInformationTableUpdateService),
        methodStr(METExciseInformationTableUpdateService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method for controller class
/// </summary>
