public static void main(Args _args)
{
    METExciseInformationTableUpdateController  metExciseInformationTableUpdateController = METExciseInformationTableUpdateController::construct();
    METExciseInformationTableUpdateController.parmArgs(_args);
    METExciseInformationTableUpdateController.startOperation();
}
